    else fill(hw(C.face[0]), C.face[1]*(1.05-f.sh*.35), cl(C.face[2]*(.35+f.sh*1.05),3,98), (xray? 24 : 96)*AL);
    sc(C.vis, wire? 70 : (xray? 46+30*glow : 62)); strokeWeight(wire? LWH : Math.max(.5,u*.0009));
    beginShape(); for (const q of f.pts) vertex(q[0],q[1]); endShape(CLOSE);
  }
  blendMode(BLEND);
  if (anno > .1){
    noStroke(); textFont('monospace'); textAlign(CENTER, TOP); textSize(Math.max(6,u*.0125));
    fc(C.anno, 70+28*anno); text('PICTORIAL - ISOMETRIC', ISO.x, ISO.y + VS*.88);
  }
}

// ---- sheet border, projection symbol, title block ---------------------------
const mgn = u*.028;
noFill(); sc(C.anno, 46+24*anno); strokeWeight(Math.max(.8,u*.0022));
rect(mgn, mgn, width-mgn*2, height-mgn*2);
sc(C.anno, 22+16*anno); strokeWeight(LWC);
rect(mgn*1.7, mgn*1.7, width-mgn*3.4, height-mgn*3.4);
if (anno > .08){
  // first/third-angle truncated-cone projection symbol
  const py3 = height - mgn*2.7, r1 = u*.015, r2 = u*.0082, hl = u*.026;
  // the frustum end-view (concentric circles) and its side view; which side they sit on IS the convention
  const cvx = mgn*2.4 + r1, svx = cvx + hl*2.4;
  const ex1 = first ? svx : cvx, ex2 = first ? cvx : svx;
  noFill(); sc(C.anno, 86); strokeWeight(Math.max(.6,u*.0013));
  ellipse(ex2, py3, r1*2, r1*2); ellipse(ex2, py3, r2*2, r2*2);
  const bigL = !first;
  const lR = bigL ? r1 : r2, rR = bigL ? r2 : r1;
  line(ex1-hl, py3-lR, ex1+hl, py3-rR); line(ex1-hl, py3+lR, ex1+hl, py3+rR);
  line(ex1-hl, py3-lR, ex1-hl, py3+lR); line(ex1+hl, py3-rR, ex1+hl, py3+rR);
  sc(C.ctr, 60); strokeWeight(LWC); ddot(Math.min(ex1,ex2)-r1*2, py3, Math.max(ex1,ex2)+r1*2, py3, u*.014);
  const px3 = mgn*2.4;
  noStroke(); textFont('monospace'); textAlign(LEFT, CENTER); textSize(Math.max(6,u*.0115));
  fc(C.anno, 80); text((first?'FIRST':'THIRD')+' ANGLE', px3 - r1, py3 + r1*2.2);
  // title block
  textAlign(RIGHT, CENTER); textSize(Math.max(7,u*.0135));
  const bx = width-mgn*2.0, by = height-mgn*2.0;
  fc(C.cell, xray?26:70); rect(bx-u*.32, by-u*.052, u*.32, u*.052);
  noFill(); sc(C.anno, 62); strokeWeight(Math.max(.5,u*.0012)); rect(bx-u*.32, by-u*.052, u*.32, u*.052);
  line(bx-u*.32, by-u*.026, bx, by-u*.026);
  noStroke(); fc(C.anno, 90);
  text('BRACKET, BOSSED - GENERAL ARRANGEMENT', bx-u*.012, by-u*.039);
  text('ALL DIMS mm   REV '+((K.section|0)+1)+'   SEED '+sd, bx-u*.012, by-u*.013);
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
